#include <iostream>
#include <vector>
#include <string>
using namespace std;

int main() {
    long long year;
    cin >> year;

    if (year % 400 == 0 || (year % 4 == 0 && year % 100 != 0)) {
        cout << "leap" << endl;
    } else {
        cout << "common" << endl;
    }

    return 0;
}

code.java:
import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long year = sc.nextLong();

        if (year % 400 == 0 || (year % 4 == 0 && year % 100 != 0)) {
            System.out.println("leap");
        } else {
            System.out.println("common");
        }
    }
}
